style.css:
@-moz-document domain("youtube.com") {
:root {
    --cream: #e9dfcc;
    --beige: #d8c8ae;
    --champagne: #f8efdf;
    --glass: rgba(244, 232, 211, 0.68);
    --glass-light: rgba(255, 250, 239, 0.82);
    --glass-border: rgba(255,255,255,0.8);
    --text: #66533d;
}

/* Main background */
html,
body,
ytd-app {
    background-color: #e8ddca !important;
    color: var(--text) !important;
}

/* Page background */
#content,
#page-manager,
ytd-browse,
ytd-watch-flexy {
    background:
        radial-gradient(ellipse at 20% 10%,
        #fff9eb 0%, transparent 45%),
        radial-gradient(ellipse at 85% 80%,
        #cbb99e 0%, transparent 50%),
        linear-gradient(135deg,
        #eee4d2, #d9c9b0) !important;
}

/* Glossy sidebar */
#guide,
ytd-mini-guide-renderer {
    background: rgba(225, 211, 188, 0.8) !important;
    backdrop-filter: blur(22px) saturate(150%);
    border-right: 1px solid var(--glass-border) !important;
}

/* Navigation */
#masthead-container,
ytd-masthead {
    background: rgba(245, 235, 218, 0.78) !important;
    backdrop-filter: blur(25px) saturate(160%);
    border-bottom: 1px solid white !important;
}

/* Video cards */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-compact-video-renderer {
    background: var(--glass) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: 18px !important;
    padding: 9px !important;
    box-shadow:
        inset 0 2px 5px rgba(255,255,255,0.85),
        inset 0 -3px 8px rgba(170,140,105,0.12),
        0 7px 20px rgba(100,75,45,0.10) !important;
    backdrop-filter: blur(18px);
    transition: 0.25s ease !important;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover {
    transform: translateY(-3px);
    background: var(--glass-light) !important;
}

/* Search bar */
#center #search-form,
#container.ytd-searchbox {
    background: rgba(255, 249, 237, 0.75) !important;
    border: 1px solid white !important;
    border-radius: 30px !important;
    box-shadow:
        inset 0 2px 5px white,
        0 4px 12px rgba(120,90,55,0.12) !important;
}

/* Search input */
#search {
    color: #725d43 !important;
}

/* Buttons */
yt-button-shape button,
ytd-button-renderer button {
    background: linear-gradient(
        145deg,
        #fff9ed,
        #dfceb3
    ) !important;
    color: #705b42 !important;
    border: 1px solid white !important;
    border-radius: 24px !important;
    box-shadow:
        inset 0 2px 4px white,
        0 3px 8px rgba(100,75,45,0.12) !important;
}

/* Video player surroundings */
#player-container-outer,
#below,
#secondary {
    border-radius: 18px !important;
}

/* Text */
h1, h2, h3,
.title,
#video-title,
yt-formatted-string {
    color: #68543d !important;
}

/* Rounded thumbnails */
ytd-thumbnail,
#thumbnail {
    border-radius: 15px !important;
    overflow: hidden !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 9px;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(
        #fff6e5,
        #cbb697
    );
    border-radius: 20px;
    border: 2px solid #e9dfcc;
}

/* Selection */
::selection {
    background: #cdb99a;
    color: white;
}
}
